{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Oral estradiol, the parent steroid of the query ester, has an absolute oral bioavailability of only 4% in postmenopausal women after a 2 mg tablet, demonstrating extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Testosterone undecanoate, a lipophilic 17β-ester prodrug of a steroid hormone, has an absolute oral bioavailability of 6.8 ± 3.3% in humans, showing that esterification does not necessarily overcome low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "2-Methoxyestradiol, another estradiol derivative, has an oral bioavailability of only 1–2% in patients, supporting the pattern of low oral bioavailability among estradiol analogs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Fulvestrant, a steroidal estrogen receptor degrader, has poor oral bioavailability requiring intramuscular administration, illustrating that steroidal estrogens often have low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Estramustine phosphate, an estradiol-based prodrug, showed a mean oral bioavailability of 43.7 ± 4.6% in patients, providing a limited counterexample that some estradiol-derived prodrugs can achieve moderate oral absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is estradiol 17-cyclopentylpropionate, an ester prodrug of estradiol. The most direct evidence shows estradiol itself has absolute oral bioavailability of only 3–11%, and a lipophilic steroid ester prodrug (testosterone undecanoate) also has low oral F (~7%). Although some estradiol-based prodrugs and ethinylestradiol show higher F, the query lacks the 17α-ethinyl metabolic protection and is not a phosphate-mustard conjugate. Therefore F is more likely below 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for estradiol cypionate in humans.",
    "Uncertainty about the extent of ester hydrolysis and possible lymphatic absorption of the cyclopentylpropionate ester.",
    "Potential formulation and food effects on oral absorption are not captured by the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

